import SwiftUI
import Combine
import Foundation
import CompositorServices
import UntoldEngine
import UntoldEngineXR

/// What the demo was launched with, for a run without hands on it (a simulator from the
/// command line): `--open-space` opens the immersive space at once, `--stats-window` opens
/// the Engine Stats window, `--log-stats` logs the engine's compact stats line once a second
/// (the same text the window shows; it needs a build with ENGINE_STATS_ENABLED).
enum LaunchOptions {
    static let arguments = CommandLine.arguments

    static var opensSpace: Bool {
        arguments.contains("--open-space")
    }

    static var opensStatsWindow: Bool {
        arguments.contains("--stats-window")
    }

    static var logsStats: Bool {
        arguments.contains("--log-stats")
    }
}



// Simple owner so the XR system doesn't deallocate.
final class XRHolder {
    static let shared = XRHolder()
    var xr: UntoldEngineXR?
    var renderThread: Thread?
}

struct UntoldEngineConfiguration: CompositorLayerConfiguration {
    func makeConfiguration(capabilities: LayerRenderer.Capabilities,
                           configuration: inout LayerRenderer.Configuration) {
        configuration.layout = .dedicated
        configuration.isFoveationEnabled = false
        configuration.colorFormat = .bgra8Unorm_srgb
    }
}

@main
struct ProceduralGeometryApp: App {

    @State private var immersionStyle: ImmersionStyle = .mixed

    var body: some SwiftUI.Scene {
        WindowGroup {
            ContentView()
        }
        .windowStyle(.plain)
        .defaultSize(width: 600, height: 400)

        WindowGroup("Engine Stats", id: "EngineStatsPanel") {
            EngineStatsWindowView(store: EngineStatsWindowStore.shared)
        }
        .defaultSize(width: 720, height: 340)

    ImmersiveSpace(id: "ImmersiveSpace") {

        CompositorLayer(configuration: UntoldEngineConfiguration(), renderer: { layerRenderer in

            // init + retain XR system
            if XRHolder.shared.xr == nil {

                if let xr = UntoldEngineXR(layerRenderer: layerRenderer) {
                    XRHolder.shared.xr = xr

                    // Set engine's immersion mode to mixed (passthrough)
                    xr.setImmersionMode(xrImmersionMode: .mixed)

                    // Initialize game scene
                    let gameScene = GameScene()

                    // Setup callbacks
                    xr.setupCallbacks(
                        gameUpdate: { deltaTime in
                            gameScene.update(deltaTime: deltaTime)
                        },
                        handleInput: {
                            gameScene.handleInput()
                        }
                    )

                    let t = Thread {
                        xr.start()      // sets isRunning = true
                        xr.runLoop()    // blocking loop - runs on dedicated thread, NOT MainActor
                    }
                    t.name = "XR Render Thread"
                    t.qualityOfService = .userInteractive
                    XRHolder.shared.renderThread = t
                    t.start()
                } else {
                    print("❌ Failed to initialize UntoldEngineXR!")
                    print("❌ LayerRenderer might be invalid or engine initialization failed")
                }
            } else {
                print("⚠️ XR system already initialized")
            }
        })
    }
        .immersionStyle(selection: $immersionStyle, in: .mixed)
    }
}

struct ContentView: View {
    @Environment(\.openImmersiveSpace) private var openImmersiveSpace
    @Environment(\.openWindow) private var openWindow
    @State private var launchOptionsApplied = false

    var body: some View {
        VStack(spacing: 30) {
            Text("ProceduralGeometry")
                .font(.extraLargeTitle)
                .fontWeight(.bold)

            Text("Powered by Untold Engine")
                .font(.title)
                .foregroundColor(.secondary)

            VStack(spacing: 4) {
                Text("Look at a wall, floor, or ceiling and pinch to place a pipe.")
                Text("Pinch a pipe to select it, then pinch it again to edit it.")
                Text("Two-hand pinch to deselect.")
            }
            .font(.body)
            .foregroundColor(.secondary)
            .multilineTextAlignment(.center)

        Button(action: {
            Task {
                await openImmersiveSpace(id: "ImmersiveSpace")
            }
        }) {
                Label("Start Experience", systemImage: "visionpro.fill")
                    .frame(minWidth: 250)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)

            Button(action: {
                openWindow(id: "EngineStatsPanel")
            }) {
                Label("Engine Stats", systemImage: "chart.xyaxis.line")
                    .frame(minWidth: 250)
            }
            .buttonStyle(.bordered)
            .controlSize(.large)
        }
        .padding(60)
        .task {
            guard !launchOptionsApplied else { return }
            launchOptionsApplied = true
            if LaunchOptions.logsStats {
                setEngineStatsLogging(enabled: true, profile: .compact, intervalSeconds: 1.0)
            }
            if LaunchOptions.opensStatsWindow {
                openWindow(id: "EngineStatsPanel")
            }
            if LaunchOptions.opensSpace {
                await openImmersiveSpace(id: "ImmersiveSpace")
            }
        }
    }
}

struct EngineStatsWindowView: View {
    @ObservedObject var store: EngineStatsWindowStore

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Text("Engine Stats")
                    .font(.headline)
                Spacer()
                Toggle("Advanced", isOn: $store.advancedMode)
                    .toggleStyle(.switch)
                    .controlSize(.small)
            }

            // The frames' stages over the last second, on a line of their own that reads on
            // the headset: the GPU span's maximum, the frames late against the refresh period
            // measured from the frames' cadence, and the worst frame's split into its CPU
            // frame, its wait for the GPU and its GPU span. The same numbers, with the same
            // definitions, as the RealityKit presenter example's numbers line.
            Text(store.stagesText)
                .font(.system(size: 15, weight: .semibold, design: .monospaced))
                .frame(maxWidth: .infinity, alignment: .leading)
                .textSelection(.enabled)

            // The eyes the frames were drawn from, in the device anchor's frame: each eye's
            // mean position in millimetres (x right, y up, z back) with half its range since
            // the stats were reset, and the distance between the two. On the headset these are
            // the user's tracked eyes, which the RealityKit presenter never sees: its example's
            // IPD and view offset are to be set to these numbers.
            Text(store.eyesText)
                .font(.system(size: 15, weight: .semibold, design: .monospaced))
                .frame(maxWidth: .infinity, alignment: .leading)
                .textSelection(.enabled)

            ScrollView {
                Text(store.advancedMode ? store.expandedText : store.compactText)
                    .font(.system(size: 12, design: .monospaced))
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .textSelection(.enabled)
            }
        }
        .padding(16)
    }
}
